#!/usr/bin/env node
/* Heavy Pockets Shopify theme: generator for the copied and generated files.
   Run: node theme/shopify/build.js
   Hand-written theme files (layout, sections, templates, theme.js, and
   hp-shopify.css) are edited directly. This script only refreshes:
     assets/brand-tokens.css, assets/site.css      (from theme/v3, the approved preview)
     assets/*.webp, *.jpg                           (hero, stones, art, size charts)
     snippets/hp-wordmark.liquid                    (from brand/v3/wordmark)
     snippets/hp-extras.liquid                      (from theme/v3/src/products.json)
   Then it checks every theme file for em dashes. No dependencies. */
'use strict';
const fs = require('fs');
const path = require('path');

const DIR = __dirname;
const ROOT = path.resolve(DIR, '../..');
const V3 = path.join(ROOT, 'theme/v3');
const read = (p) => JSON.parse(fs.readFileSync(p, 'utf8'));
const SRC = read(path.join(V3, 'src/products.json'));
const SNAP = read(path.join(V3, 'src/printify-snapshot.json'));
const ASSETS = path.join(DIR, 'assets');
const SNIPS = path.join(DIR, 'snippets');
fs.mkdirSync(ASSETS, { recursive: true });
fs.mkdirSync(SNIPS, { recursive: true });

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const noDash = (s) => s.replace(/\s*\u2014\s*/g, ': ');

/* ---------- styles: the approved v3 CSS, unchanged except comments ---------- */
fs.writeFileSync(path.join(ASSETS, 'brand-tokens.css'), noDash(fs.readFileSync(path.join(V3, 'assets/brand-tokens.css'), 'utf8')));
fs.writeFileSync(path.join(ASSETS, 'site.css'), '/* Copied from theme/v3/assets/site.css by theme/shopify/build.js. Edit v3, then rebuild. Shopify-only rules live in hp-shopify.css. */\n' +
  noDash(fs.readFileSync(path.join(V3, 'assets/site.css'), 'utf8')));

/* ---------- images (Shopify assets are one flat folder) ---------- */
const copies = [
  ['img/hero/shore-wide.webp', 'hero-shore-wide.webp'], ['img/hero/shore-wide.jpg', 'hero-shore-wide.jpg'],
  ['img/hero/shore-tall.webp', 'hero-shore-tall.webp'], ['img/hero/shore-tall.jpg', 'hero-shore-tall.jpg'],
  ['img/size-chart-tee.webp', 'size-chart-tee.webp'], ['img/size-chart-hoodie.webp', 'size-chart-hoodie.webp'],
];
for (const s of ['agate-hero', 'jasper', 'petoskey', 'leland']) for (const st of ['dry', 'wet']) copies.push([`img/stones/${s}-${st}.webp`, `stone-${s}-${st}.webp`]);
const artName = (src) => 'art-' + path.basename(src);
// Width and height of a WebP file (VP8, VP8L, or VP8X), so every <img> has its size.
function webpSize(file) {
  const b = fs.readFileSync(file);
  const kind = b.toString('ascii', 12, 16);
  if (kind === 'VP8X') return [1 + b.readUIntLE(24, 3), 1 + b.readUIntLE(27, 3)];
  if (kind === 'VP8L') { const n = b.readUInt32LE(21); return [1 + (n & 0x3fff), 1 + ((n >> 14) & 0x3fff)]; }
  if (kind === 'VP8 ') return [b.readUInt16LE(26) & 0x3fff, b.readUInt16LE(28) & 0x3fff];
  throw new Error('not a webp: ' + file);
}
const dims = (src) => webpSize(path.join(V3, src));
SRC.products.forEach((p) => p.art.forEach((a) => copies.push([a.src, artName(a.src)])));
for (const [from, to] of copies) fs.copyFileSync(path.join(V3, from), path.join(ASSETS, to));

/* ---------- wordmark ---------- */
const WORDMARK = fs.readFileSync(path.join(ROOT, 'brand/v3/wordmark/heavy-pockets-wordmark.svg'), 'utf8')
  .trim().replace('<svg ', '<svg class="wordmark" focusable="false" aria-hidden="true" ').replace(/ role="img" aria-label="[^"]*"/, '');
fs.writeFileSync(path.join(SNIPS, 'hp-wordmark.liquid'), '{%- comment -%} Generated by build.js from brand/v3/wordmark. Do not edit by hand. {%- endcomment -%}\n' + WORDMARK + '\n');

/* ---------- per-product extras ----------
   Shopify holds the products, variants, prices, and photos (published from Printify).
   The approved v3 copy (blurb, story, decoration, fabric, fit, care, and art files),
   the preferred color order, swatch colors, and Printify's mockup order live here,
   keyed by product handle. Usage:
     {% render 'hp-extras', handle: product.handle, field: 'story' %}
   Fields: kind, blurb, story, decoration, colors (pipe list), hexes (pipe list),
   views (pipe list of mockup labels, in Printify's image order), card_index,
   info (the info blocks HTML), handles (curated order, any handle). */
const VIEWS = {
  cc1717: ['Front', 'Back', 'Folded', 'Styled flat lay'],
  g18500: ['Front', 'Back', 'Back with hood up', 'Folded'],
};
// v3 used a cropped close-up of the front for two cards; Shopify only has the full front mockup.
const CARD_INDEX = { front: 0, 'front-close': 0, back: 1 };

function infoHtml(p) {
  const blank = SRC.blanks[p.blank];
  const care = p.care ? blank[p.care] : blank.care;
  const chart = path.basename(blank.chart);
  const figs = p.art.map((a) => `<figure class="art-fig art-fig--${a.bg}"><img src="{{ '${artName(a.src)}' | asset_url }}" width="${dims(a.src)[0]}" height="${dims(a.src)[1]}" alt="${esc(p.name)}: ${esc(a.label.toLowerCase())}, shown as the design file" loading="lazy" decoding="async"><figcaption>${esc(a.label)}. Design file preview, not a photo of a printed ${p.kind.toLowerCase()}.</figcaption></figure>`).join('');
  return `<section class="info__block info__block--wide">
      <h2>The design</h2>
      <p>${esc(p.story)}</p>
      <div class="art-figs">${figs}</div>
      <p class="small">Images are mockups. Photos of the finished pieces are coming.</p>
    </section>
    <section class="info__block">
      <h2>Fit and sizing</h2>
      <p>${esc(blank.fit)}</p>
      <figure class="chart"><img src="{{ '${chart}' | asset_url }}" width="${dims(blank.chart)[0]}" height="${dims(blank.chart)[1]}" alt="Size chart for the ${esc(blank.name)}, with body width, length, and sleeve length by size in inches and centimeters." loading="lazy" decoding="async"><figcaption>Size chart. Measure a shirt you like and compare.</figcaption></figure>
    </section>
    <section class="info__block">
      <h2>Fabric</h2>
      <p>${esc(blank.name)}.</p>
      <ul>${blank.fabric.map((f) => `<li>${esc(f)}</li>`).join('')}</ul>
    </section>
    <section class="info__block">
      <h2>Decoration</h2>
      <p>${esc(p.decoration)}</p>
      <p>Made to order for you.</p>
    </section>
    <section class="info__block">
      <h2>Care</h2>
      <ul>${care.map((f) => `<li>${esc(f)}</li>`).join('')}</ul>
    </section>`;
}

const errors = [];
let out = '{%- comment -%} Generated by theme/shopify/build.js from theme/v3/src/products.json. Do not edit by hand. {%- endcomment -%}\n';
out += `{%- if field == 'handles' -%}${SRC.products.map((p) => p.slug).join('|')}{%- else -%}\n{%- case handle -%}\n`;
for (const p of SRC.products) {
  const snap = SNAP.products[p.slug];
  if (!snap) { errors.push('no snapshot for ' + p.slug); continue; }
  if (p.colors.some((c) => /indigo/i.test(c))) errors.push(p.slug + ': Indigo Blue must not be offered');
  const hexes = p.colors.map((c) => snap.swatches[c]);
  hexes.forEach((h, i) => { if (!/^#[0-9A-F]{6}$/i.test(h || '')) errors.push(`${p.slug}/${p.colors[i]}: bad swatch`); });
  if (!(p.card_view in CARD_INDEX)) errors.push(p.slug + ': unknown card_view ' + p.card_view);
  const fields = {
    kind: esc(p.kind), blurb: esc(p.blurb), story: esc(p.story), decoration: esc(p.decoration),
    colors: p.colors.join('|'), hexes: hexes.join('|'), views: VIEWS[p.blank].join('|'),
    card_index: String(CARD_INDEX[p.card_view]), info: infoHtml(p),
  };
  out += `{%- when '${p.slug}' -%}\n{%- case field -%}\n`;
  for (const [k, v] of Object.entries(fields)) out += `{%- when '${k}' -%}${v}\n`;
  out += '{%- endcase -%}\n';
}
out += '{%- endcase -%}\n{%- endif -%}\n';
fs.writeFileSync(path.join(SNIPS, 'hp-extras.liquid'), out);
if (errors.length) { console.error(errors.join('\n')); process.exit(1); }

/* ---------- house rule: no em dashes anywhere in the theme ---------- */
function walk(d) { return fs.readdirSync(d, { withFileTypes: true }).flatMap((e) => e.isDirectory() ? walk(path.join(d, e.name)) : [path.join(d, e.name)]); }
const bad = walk(DIR).filter((f) => /\.(liquid|json|js|css|md)$/.test(f) && !f.includes('node_modules') && /\u2014/.test(fs.readFileSync(f, 'utf8')));
if (bad.length) { console.error('Em dash found in:\n' + bad.map((f) => path.relative(DIR, f)).join('\n')); process.exit(1); }
console.log('theme assets and snippets refreshed:', copies.length, 'images,', SRC.products.length, 'products');
